        atm_addr->sat_addr.itf = vcc->vcc_sap->sap_addr.itf;
        atm_addr->sat_addr.vpi = vcc->vcc_sap->sap_addr.vpi;
        atm_addr->sat_addr.vci = vcc->vcc_sap->sap_addr.vci;
