    }

    *sockaddr_len = sizeof(*atm_addr);
    return 0;
}

int get_socket_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer) {
    struct atm_vcc *vcc = sock->sk.atm_vcc;
    struct sockaddr_atm *atm_addr = (struct sockaddr_atm *)sockaddr;

    if (!vcc || (!peer && !vcc->remote) || (peer && !vcc->local)) {
        return -ENOTCONN;
    }

    if (!peer) {
        atm_addr->satosap = ATM_SAP_PVC;
        atm_addr->address.itf = vcc->local->dev->number;
        atm_addr->address.vpi = vcc->local->vpi;
        atm_addr->address.vci = vcc->local->vci;
    } else {
        atm_addr->satosap = ATM_SAP_PVC;
        atm_addr->address.itf = vcc->remote->dev->number;
        atm_addr->address.vpi = vcc->remote->vpi;
        atm_addr->address.vci = vcc->remote->vci;
    }

    *sockaddr_len = sizeof(*atm_addr);
    return 0;
}

#include <linux/atm.h>
#include <linux/sockios.h>
#include <linux/errno.h>

int get_sock_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer) {
    struct atm_vcc *vcc = ATM_SD(sock);

    if (!vcc || !vcc->dev) {
        return -ENOTCONN;
    }

    if (peer) {
        if (!vcc->remote) {
            return -ENOTCONN;
        }

        *(struct atm_address *)sockaddr = vcc->remote->address;
    } else {
        *(struct atm_address *)sockaddr = vcc->local;
    }

    ((struct sockaddr_atmpvc *)sockaddr)->salempl = 0;
    ((struct sockaddr_atmpvc *)sockaddr)->address.itf = vcc->ci;
    ((struct sockaddr_atmpvc *)sockaddr)->address.vpi = vcc->vpi;
    ((struct sockaddr_atmpvc *)sockaddr)->address.vci = vcc->vci;
    *sockaddr_len = sizeof(struct sockaddr_atmpvc);

    return 0;
}

int get_sock_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer)
{
    struct atm_vcc *vcc = sock->sk.atm_vcc;

    if (!vcc || (peer && !vcc->remote) || (!peer && !vcc->local))
        return -ENOTCONN;

    if (peer) {
        sockaddr->sa_family = AF_ATMPVC;
        ((struct sockaddr_atmpvc *)sockaddr)->sat_addr.addr_type = ATM_AVP_PVC;
        ((struct sockaddr_atmpvc *)sockaddr)->sat_addr.addr.vpi = vcc->remote_vpi;
        ((struct sockaddr_atmpvc *)sockaddr)->sat_addr.addr.vci = vcc->remote_vci;
        ((struct sockaddr_atmpvc *)sockaddr)->sat_addr.dev = vcc->dev;
    } else {
        sockaddr->sa_family = AF_ATMPVC;
        ((struct sockaddr_atmpvc *)sockaddr)->sat_addr.addr_type = ATM_AVP_PVC;
        ((struct sockaddr_atmpvc *)sockaddr)->sat_addr.addr.vpi = vcc->local_vpi;
        ((struct sockaddr_atmpvc *)sockaddr)->sat_addr.addr.vci = vcc->local_vci;
        ((struct sockaddr_atmpvc *)sockaddr)->sat_addr.dev = vcc->dev;
    }

    *sockaddr_len = sizeof(struct sockaddr_atmpvc);
    return 0;
}

int get_sock_name(struct socket *sock, struct sockaddr *sockaddr, int *sockaddr_len, int peer)
{
    struct atm_vcc *vcc = sock->sk.atm_vcc;
    struct sockaddr_atm *saatm;

    if (!vcc || (peer && !vcc->peer_vcc))
        return -ENOTCONN;

    if (sockaddr == NULL || sockaddr_len == NULL)
        return -EINVAL;

    saatm = (struct sockaddr_atm *)sockaddr;
    memset(saatm, 0, sizeof(struct sockaddr_atm));
    saatm->sac_family = AF_ATMPVC;

    if (peer) {
        saatm->sac_addr = vcc->peer_vcc->local;
    } else {
        saatm->sac_addr = vcc->local;
    }

    *sockaddr_len = sizeof(struct sockaddr_atm);
    return 0;
}
